import{_ as a,o as t,c as n,a3 as o}from"./chunks/framework.Cc-oPviL.js";const u=JSON.parse('{"title":"04 · HTTP / HTTPS 与缓存","description":"","frontmatter":{},"headers":[],"relativePath":"bagu/network/04.md","filePath":"bagu/network/04.md"}'),e={name:"bagu/network/04.md"};function p(l,s,i,d,r,c){return t(),n("div",null,[...s[0]||(s[0]=[o(`<h1 id="_04-·-http-https-与缓存" tabindex="-1">04 · HTTP / HTTPS 与缓存 <a class="header-anchor" href="#_04-·-http-https-与缓存" aria-label="Permalink to &quot;04 · HTTP / HTTPS 与缓存&quot;">​</a></h1><blockquote><p>传输层保证&quot;数据能到&quot;，应用层决定&quot;数据长什么样、能不能被缓存、安不安全&quot;。</p></blockquote><h2 id="一句话本质" tabindex="-1">一句话本质 <a class="header-anchor" href="#一句话本质" aria-label="Permalink to &quot;一句话本质&quot;">​</a></h2><p>HTTP 是<strong>一问一答的文本协议</strong>：客户端说&quot;我要什么&quot;，服务器说&quot;给你 / 没有 / 你去别处拿&quot;。HTTPS 就是在它和 TCP 之间插了一层加密。</p><h2 id="生活类比-点餐与取餐" tabindex="-1">生活类比：点餐与取餐 <a class="header-anchor" href="#生活类比-点餐与取餐" aria-label="Permalink to &quot;生活类比：点餐与取餐&quot;">​</a></h2><table tabindex="0"><thead><tr><th>HTTP 概念</th><th>餐厅</th></tr></thead><tbody><tr><td>请求方法</td><td>GET = &quot;给我看看菜单&quot;；POST = &quot;我下单&quot;；PUT = &quot;把这道菜换成新的&quot;；DELETE = &quot;退掉&quot;</td></tr><tr><td>状态码</td><td>200 上菜了；301 换到隔壁店了；404 没这道菜；500 后厨炸了</td></tr><tr><td>请求头</td><td>忌口说明（我要微辣、不要香菜）</td></tr><tr><td>响应头</td><td>出餐说明（这道菜 10 分钟内吃完、保质期到明天）</td></tr><tr><td>强缓存</td><td>&quot;这道菜你自己留着，2 小时内别再点&quot;</td></tr><tr><td>协商缓存</td><td>&quot;你上次点的那份还在，还是老样子吗？&quot; → &quot;没变，用你那份&quot;</td></tr><tr><td>HTTPS</td><td>菜单和订单都装进密封袋，中间人看不到</td></tr></tbody></table><h2 id="核心机制" tabindex="-1">核心机制 <a class="header-anchor" href="#核心机制" aria-label="Permalink to &quot;核心机制&quot;">​</a></h2><h3 id="一、报文结构" tabindex="-1">一、报文结构 <a class="header-anchor" href="#一、报文结构" aria-label="Permalink to &quot;一、报文结构&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>请求：</span></span>
<span class="line"><span>  GET /index.html?page=2 HTTP/1.1        &lt; 请求行：方法 + 路径 + 版本</span></span>
<span class="line"><span>  Host: example.com                       &lt; 请求头</span></span>
<span class="line"><span>  User-Agent: Chrome/120</span></span>
<span class="line"><span>  Accept: text/html</span></span>
<span class="line"><span>  Cookie: sid=abc123</span></span>
<span class="line"><span>                                          &lt; 空行（必须有）</span></span>
<span class="line"><span>  （GET 通常没有 body；POST 有）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>响应：</span></span>
<span class="line"><span>  HTTP/1.1 200 OK                         &lt; 状态行：版本 + 状态码 + 短语</span></span>
<span class="line"><span>  Content-Type: text/html; charset=utf-8   &lt; 响应头</span></span>
<span class="line"><span>  Content-Length: 1024</span></span>
<span class="line"><span>  Cache-Control: max-age=3600</span></span>
<span class="line"><span>                                          &lt; 空行</span></span>
<span class="line"><span>  &lt;html&gt;...&lt;/html&gt;                        &lt; 响应体</span></span></code></pre></div><h3 id="二、方法-幂等与安全-高频" tabindex="-1">二、方法：幂等与安全（高频） <a class="header-anchor" href="#二、方法-幂等与安全-高频" aria-label="Permalink to &quot;二、方法：幂等与安全（高频）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>方法</th><th>语义</th><th>安全</th><th>幂等</th><th>有无 body</th></tr></thead><tbody><tr><td>GET</td><td>获取资源</td><td>✅</td><td>✅</td><td>无</td></tr><tr><td>HEAD</td><td>只要响应头</td><td>✅</td><td>✅</td><td>无</td></tr><tr><td>POST</td><td>提交数据 / 创建</td><td>❌</td><td>❌</td><td>有</td></tr><tr><td>PUT</td><td>全量替换</td><td>❌</td><td>✅</td><td>有</td></tr><tr><td>PATCH</td><td>局部更新</td><td>❌</td><td>❌</td><td>有</td></tr><tr><td>DELETE</td><td>删除</td><td>❌</td><td>✅</td><td>无</td></tr></tbody></table><p><strong>安全</strong> = 不改变服务器状态（只读）。 <strong>幂等</strong> = 执行 1 次和执行 N 次，服务器状态相同。</p><p><strong>为什么重要</strong>：网络会重试。GET/PUT/DELETE 重试没问题，<strong>POST 重试会重复下单</strong>——这就是&quot;支付接口必须用幂等键&quot;的原因。</p><h3 id="三、状态码-记住-段位" tabindex="-1">三、状态码：记住&quot;段位&quot; <a class="header-anchor" href="#三、状态码-记住-段位" aria-label="Permalink to &quot;三、状态码：记住&quot;段位&quot;&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1xx  信息     100 Continue（我先发个头，你确认再发 body）</span></span>
<span class="line"><span>2xx  成功     200 OK / 201 Created / 204 No Content</span></span>
<span class="line"><span>3xx  重定向   301 永久（浏览器会缓存，下次直接跳）</span></span>
<span class="line"><span>              302 临时（每次都要问）</span></span>
<span class="line"><span>              304 未修改（协商缓存命中，用本地副本）</span></span>
<span class="line"><span>4xx  客户端错 400 参数错 / 401 没认证 / 403 没权限 / 404 不存在 / 429 太频繁</span></span>
<span class="line"><span>5xx  服务端错 500 内部错误 / 502 网关收到上游的坏响应 / 503 服务不可用 / 504 网关超时</span></span></code></pre></div><p><strong>两个易混点</strong>：</p><ul><li><strong>401 vs 403</strong>：401 是&quot;你没登录&quot;（不知道你是谁），403 是&quot;知道你是谁，但你没权限&quot;。</li><li><strong>502 vs 504</strong>：502 是上游返回了非法响应（进程崩了、协议错），504 是上游没响应（超时）。<strong>502 常见于上游进程挂了，504 常见于上游处理太慢</strong>。</li></ul><h3 id="四、http-版本演进-一条主线-不断减少往返" tabindex="-1">四、HTTP 版本演进（一条主线：不断减少往返） <a class="header-anchor" href="#四、http-版本演进-一条主线-不断减少往返" aria-label="Permalink to &quot;四、HTTP 版本演进（一条主线：不断减少往返）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>HTTP/1.0  每个请求一个 TCP 连接，用完就关</span></span>
<span class="line"><span>          +- 问题：每次都要三次握手，太慢</span></span>
<span class="line"><span>              v</span></span>
<span class="line"><span>HTTP/1.1  ① 持久连接（keep-alive），复用 TCP 连接</span></span>
<span class="line"><span>          ② 管道化（pipelining）：可以连着发多个请求，但**响应必须按序返回**</span></span>
<span class="line"><span>             +- 问题：队头阻塞，一个慢请求卡住后面全部</span></span>
<span class="line"><span>          ③ Host 头（支持虚拟主机，一个 IP 多个域名）</span></span>
<span class="line"><span>          ④ 分块传输（chunked）、断点续传（Range）</span></span>
<span class="line"><span>              v</span></span>
<span class="line"><span>HTTP/2    ① 二进制分帧（不再是文本）</span></span>
<span class="line"><span>          ② 多路复用：一个 TCP 连接上跑多个流，每个流有自己的 ID</span></span>
<span class="line"><span>             +- 解决了 HTTP 层的队头阻塞</span></span>
<span class="line"><span>          ③ 头部压缩（HPACK，用静态表 + 动态表，避免重复传相同的头）</span></span>
<span class="line"><span>          ④ 服务器推送（Server Push，实际用得少，已被废弃）</span></span>
<span class="line"><span>             +- 问题：底层还是 TCP，TCP 丢包会阻塞所有流</span></span>
<span class="line"><span>              v</span></span>
<span class="line"><span>HTTP/3    基于 QUIC（跑在 UDP 上）</span></span>
<span class="line"><span>          ① 每个流独立排序，彻底解决队头阻塞</span></span>
<span class="line"><span>          ② 0-RTT / 1-RTT 建连（TLS 1.3 集成在 QUIC 里）</span></span>
<span class="line"><span>          ③ 连接迁移（换网络不用重连，靠 Connection ID 而不是四元组）</span></span></code></pre></div><p><strong>面试必答的一句话</strong>：<strong>HTTP/2 解决的是应用层队头阻塞，没解决 TCP 层队头阻塞；HTTP/3 用 QUIC 才彻底解决。</strong></p><h3 id="五、缓存-两道关卡" tabindex="-1">五、缓存：两道关卡 <a class="header-anchor" href="#五、缓存-两道关卡" aria-label="Permalink to &quot;五、缓存：两道关卡&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>浏览器要请求一个资源</span></span>
<span class="line"><span>   v</span></span>
<span class="line"><span>① 强缓存：本地有，且没过期？</span></span>
<span class="line"><span>   Cache-Control: max-age=3600      （相对时间，优先）</span></span>
<span class="line"><span>   Expires: Wed, 21 Oct 2026 ...    （绝对时间，会被本地时间影响，已过时）</span></span>
<span class="line"><span>   +- 没过期 &gt; 直接用本地，**不发请求**（状态码显示 200 from disk cache）</span></span>
<span class="line"><span>   +- 过期了 v</span></span>
<span class="line"><span>② 协商缓存：带上标识问服务器&quot;变了吗&quot;</span></span>
<span class="line"><span>   If-None-Match: &quot;abc123&quot;   &lt; 对应 ETag（内容哈希，精确）</span></span>
<span class="line"><span>   If-Modified-Since: ...    &lt; 对应 Last-Modified（文件修改时间，精度只到秒）</span></span>
<span class="line"><span>   +- 没变 &gt; 304 Not Modified，**不传 body**，用本地副本</span></span>
<span class="line"><span>   +- 变了 &gt; 200，返回新内容</span></span></code></pre></div><p><strong>为什么 ETag 优先于 Last-Modified</strong>：</p><ul><li>Last-Modified 只精确到秒，一秒内改两次识别不出来。</li><li>文件被 touch 但内容没变，Last-Modified 会变，导致不必要的重传。</li><li>ETag 是内容哈希，精确。</li></ul><p><strong><code>Cache-Control</code> 的关键值</strong>：</p><table tabindex="0"><thead><tr><th>值</th><th>含义</th></tr></thead><tbody><tr><td><code>max-age=3600</code></td><td>强缓存 1 小时</td></tr><tr><td><code>no-cache</code></td><td><strong>可以缓存，但每次都要协商</strong>（不是&quot;不缓存&quot;！）</td></tr><tr><td><code>no-store</code></td><td>完全不缓存（敏感数据）</td></tr><tr><td><code>private</code></td><td>只允许浏览器缓存，CDN 不许</td></tr><tr><td><code>public</code></td><td>允许 CDN 等中间代理缓存</td></tr><tr><td><code>immutable</code></td><td>内容永不改变，连协商都省了（配合带哈希的文件名）</td></tr></tbody></table><p><strong>注意 <code>no-cache</code> 的坑</strong>：名字叫&quot;不缓存&quot;，实际是&quot;缓存但必须校验&quot;。真正不缓存是 <code>no-store</code>。这是面试常见陷阱。</p><h3 id="六、https-tls-握手做了什么" tabindex="-1">六、HTTPS：TLS 握手做了什么 <a class="header-anchor" href="#六、https-tls-握手做了什么" aria-label="Permalink to &quot;六、HTTPS：TLS 握手做了什么&quot;">​</a></h3><p>HTTPS = HTTP + TLS。TLS 要解决三件事：<strong>机密性（加密）、完整性（防篡改）、身份认证（防冒充）</strong>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>TLS 1.2 握手（简化，2-RTT）：</span></span>
<span class="line"><span>① 客户端 &gt; 服务器：ClientHello（支持的加密套件、随机数 A）</span></span>
<span class="line"><span>② 服务器 &gt; 客户端：ServerHello（选定的套件、随机数 B）+ 证书</span></span>
<span class="line"><span>③ 客户端验证证书（查 CA 签名、查域名、查有效期、查吊销状态）</span></span>
<span class="line"><span>④ 客户端用证书里的公钥加密&quot;预主密钥&quot;发给服务器</span></span>
<span class="line"><span>⑤ 双方用 随机数A + 随机数B + 预主密钥 算出相同的会话密钥</span></span>
<span class="line"><span>⑥ 之后用对称加密通信</span></span>
<span class="line"><span></span></span>
<span class="line"><span>TLS 1.3（1-RTT，甚至 0-RTT）：</span></span>
<span class="line"><span>  合并了握手轮次，删掉了不安全的算法（RSA 密钥交换、CBC 模式等）</span></span></code></pre></div><p><strong>为什么用&quot;非对称 + 对称&quot;混合</strong>：</p><ul><li><strong>非对称加密（RSA/ECDHE）</strong>：安全但慢（慢几百倍），只用来<strong>协商密钥</strong>。</li><li><strong>对称加密（AES/ChaCha20）</strong>：快，用来<strong>加密真正的数据</strong>。</li><li>一句话：<strong>用非对称的&quot;安全&quot;来传递对称的&quot;钥匙&quot;</strong>。</li></ul><p><strong>证书链</strong>：服务器证书 &gt; 中间 CA &gt; 根 CA（内置在浏览器/系统里）。浏览器逐级验证签名，直到信任的根。这就是为什么&quot;自签名证书&quot;会报警——没有可信的根为它背书。</p><h2 id="为什么这么设计" tabindex="-1">为什么这么设计 <a class="header-anchor" href="#为什么这么设计" aria-label="Permalink to &quot;为什么这么设计&quot;">​</a></h2><h3 id="反事实-1-如果-http-不加密" tabindex="-1">反事实 1：如果 HTTP 不加密 <a class="header-anchor" href="#反事实-1-如果-http-不加密" aria-label="Permalink to &quot;反事实 1：如果 HTTP 不加密&quot;">​</a></h3><ul><li>同一 WiFi 下的人能看到你所有的请求内容（明文）。</li><li>中间人可以篡改响应（往网页里插广告、改支付账号）。</li><li>无法确认&quot;你连的真的是银行网站&quot;（DNS 劫持 + 假冒服务器）。</li></ul><h3 id="反事实-2-如果只用非对称加密" tabindex="-1">反事实 2：如果只用非对称加密 <a class="header-anchor" href="#反事实-2-如果只用非对称加密" aria-label="Permalink to &quot;反事实 2：如果只用非对称加密&quot;">​</a></h3><p>每个请求都要做一次 RSA 运算，比对称加密慢 2~3 个数量级。一个网页几十个请求，CPU 直接爆。</p><h3 id="反事实-3-如果没有缓存" tabindex="-1">反事实 3：如果没有缓存 <a class="header-anchor" href="#反事实-3-如果没有缓存" aria-label="Permalink to &quot;反事实 3：如果没有缓存&quot;">​</a></h3><p>每次打开网页都要重新下载所有资源。一个 2MB 的页面，弱网下要十几秒。缓存把&quot;重复下载&quot;变成&quot;问一句变没变&quot;（304 响应只有几百字节）。</p><h2 id="面试怎么问" tabindex="-1">面试怎么问 <a class="header-anchor" href="#面试怎么问" aria-label="Permalink to &quot;面试怎么问&quot;">​</a></h2><p><strong>Q：HTTP/1.1、HTTP/2、HTTP/3 的区别？</strong></p><blockquote><p>一条主线：<strong>都在解决&quot;往返次数&quot;和&quot;队头阻塞&quot;</strong>。 1.1 加持久连接（省握手）、加管道化（但响应必须按序，队头阻塞没解决）。 2.0 二进制分帧 + 多路复用（解决应用层队头阻塞）+ 头部压缩。 3.0 换 QUIC（UDP），解决 TCP 层队头阻塞 + 更快的建连 + 连接迁移。</p></blockquote><p><strong>Q：强缓存和协商缓存的区别？</strong></p><blockquote><p>强缓存<strong>不发请求</strong>，直接看本地是否过期（<code>Cache-Control: max-age</code>）。 协商缓存<strong>要发请求</strong>，带 <code>If-None-Match</code> / <code>If-Modified-Since</code>，服务器判断没变就回 304（不带 body）。 顺序：先强缓存，过期了才走协商。</p></blockquote><p><strong>Q：HTTPS 的握手过程？为什么要非对称 + 对称？</strong></p><blockquote><p>非对称只用来协商密钥（安全但慢），对称用来传数据（快）。证书解决&quot;我怎么确认公钥是你的&quot;这个问题。</p></blockquote><p><strong>Q：为什么 HTTPS 能防中间人？</strong></p><blockquote><p>因为证书由 CA 签名，浏览器内置了可信根。中间人伪造证书需要 CA 的私钥，做不到；用自签证书浏览器会报警。 <strong>但要补一句</strong>：如果用户手动信任了恶意根证书（或系统被装后门），HTTPS 也防不住。</p></blockquote><p><strong>追问链</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>HTTP 和 HTTPS 区别？</span></span>
<span class="line"><span>  &gt; HTTPS 怎么加密？（TLS）</span></span>
<span class="line"><span>    &gt; 用对称还是非对称？（混合：非对称协商密钥，对称传数据）</span></span>
<span class="line"><span>      &gt; 为什么不全用非对称？（慢几百倍）</span></span>
<span class="line"><span>        &gt; 怎么确认公钥是对方的？（证书 + CA 签名）</span></span>
<span class="line"><span>          &gt; 证书链怎么验证？（逐级验签到内置根）</span></span>
<span class="line"><span>            &gt; 那中间人能解密吗？（不能，没有私钥）</span></span></code></pre></div><h2 id="和其他知识的连接" tabindex="-1">和其他知识的连接 <a class="header-anchor" href="#和其他知识的连接" aria-label="Permalink to &quot;和其他知识的连接&quot;">​</a></h2><ul><li><strong>&lt; 来自</strong> <a href="/study-hub/bagu/network/02">TCP 连接管理：三次握手、四次挥手、TIME_WAIT</a>：keep-alive 复用 TCP 连接，省掉反复握手</li><li><strong>&lt; 来自</strong> <a href="/study-hub/bagu/network/03">TCP 可靠传输与拥塞控制</a>：TCP 队头阻塞是 HTTP/2 的瓶颈，催生了 HTTP/3</li><li><strong>&gt; 影响</strong> <a href="/study-hub/bagu/network/05">DNS 与 ARP：两个&quot;翻译官&quot;</a>：DNS 查询本身也走 HTTP（DoH）或 UDP</li><li><strong>&gt; 影响</strong> 工程实践：CDN 缓存策略、静态资源指纹（<code>app.a1b2c3.js</code>）、<code>immutable</code>、Service Worker 离线缓存</li><li><strong>&gt; 影响</strong> 安全：CSRF 靠 Cookie 的 <code>SameSite</code>、XSS 靠 CSP、点击劫持靠 <code>X-Frame-Options</code></li></ul><h2 id="自测-3-问" tabindex="-1">自测 3 问 <a class="header-anchor" href="#自测-3-问" aria-label="Permalink to &quot;自测 3 问&quot;">​</a></h2><p><strong>Q1：<code>Cache-Control: no-cache</code> 和 <code>no-store</code> 有什么区别？</strong></p><details class="details custom-block"><summary>点开看答案</summary><ul><li><strong><code>no-cache</code></strong>：<strong>可以缓存</strong>，但每次使用前必须向服务器确认（走协商缓存）。名字有误导性，它禁止的不是&quot;缓存&quot;，而是&quot;直接用缓存&quot;。</li><li><strong><code>no-store</code></strong>：<strong>完全禁止缓存</strong>，不写磁盘、不写内存，每次都重新请求。</li></ul><p>什么时候用：</p><ul><li>内容会变但想省流量 &gt; <code>no-cache</code>（用 ETag 协商，没变就 304）。</li><li>敏感数据（银行页面、token） &gt; <code>no-store</code>（连本地副本都不留）。</li></ul><p>这是最经典的 HTTP 缓存陷阱题。</p></details><p><strong>Q2：为什么 HTTP/2 的多路复用不能解决 TCP 队头阻塞？</strong></p><details class="details custom-block"><summary>点开看答案</summary><p>因为 HTTP/2 的多路复用是<strong>在 TCP 之上</strong>做的：多个流被切成帧，交错发在<strong>同一条 TCP 连接</strong>里。</p><p>而 TCP 是&quot;按序交付的字节流&quot;，它不知道帧的边界。一旦某个 TCP 段丢了，<strong>后面的所有字节都要在内核缓冲区里等</strong>，包括其他流的帧。</p><p>所以：</p><ul><li>HTTP/1.1 的队头阻塞在<strong>应用层</strong>（一个请求慢，后面排队）。</li><li>HTTP/2 解决了应用层的，但把问题下沉到了 <strong>TCP 层</strong>——而且更糟：所有流挤在一条连接上，一个丢包卡住全部。</li></ul><p>HTTP/3 用 QUIC 在用户态实现可靠传输，每个流独立编号、独立重传，才真正做到&quot;一个流丢包不影响其他流&quot;。</p></details><p><strong>Q3：为什么 502 和 504 要分开？</strong></p><details class="details custom-block"><summary>点开看答案</summary><p>因为它们指向<strong>完全不同的故障</strong>，排查方向相反：</p><ul><li><strong>502 Bad Gateway</strong>：网关（Nginx）连上了上游，但上游返回了<strong>非法响应</strong>（连接被重置、响应格式错、进程崩了）。&gt; 去查<strong>上游进程是否存活</strong>、日志有没有崩溃。</li><li><strong>504 Gateway Timeout</strong>：网关连上了上游，也发了请求，但<strong>上游在超时时间内没回</strong>。&gt; 去查<strong>上游为什么慢</strong>（慢 SQL、下游依赖、死锁）。</li></ul><p>一个&quot;坏了&quot;，一个&quot;慢了&quot;，处理方式完全不同。这是线上排障的基本功。</p></details><h2 id="类比失效处-易错点" tabindex="-1">类比失效处 / 易错点 <a class="header-anchor" href="#类比失效处-易错点" aria-label="Permalink to &quot;类比失效处 / 易错点&quot;">​</a></h2><ul><li><strong>&quot;一问一答&quot;会让人以为 HTTP/1.1 不能并发</strong>。实际上浏览器会开 6 个左右的 TCP 连接并行请求。</li><li><strong>HTTP 是无状态的，但 Cookie 让它&quot;看起来有状态&quot;</strong>。状态存在客户端，服务器每次都要重新识别——所以才有 Session、Token。</li><li><strong>301 会被浏览器永久缓存</strong>。发错了很难撤回（用户清了缓存才恢复），所以不确定时用 302/307。</li><li><strong>HTTPS 不加密域名（SNI 明文）</strong>。中间人能看到你访问哪个网站，只是看不到内容。ECH（Encrypted Client Hello）在解决这个问题，但还没普及。</li><li><strong><code>max-age</code> 是相对时间，<code>Expires</code> 是绝对时间</strong>。<code>Expires</code> 依赖客户端时钟，时钟不准就失效，所以现代都用 <code>max-age</code>。</li><li><strong>HTTP/2 的 Server Push 已经被主流放弃</strong>（Chrome 已移除），别在面试里当亮点讲。</li></ul><h2 id="✅-验收清单" tabindex="-1">✅ 验收清单 <a class="header-anchor" href="#✅-验收清单" aria-label="Permalink to &quot;✅ 验收清单&quot;">​</a></h2><ul><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="0"> 能写出一个完整的 HTTP 请求报文和响应报文（含请求行/状态行、头、空行、body）</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="1"> 能说出 GET 和 POST 在&quot;安全/幂等&quot;上的区别，并解释为什么支付接口要幂等键</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="2"> 能区分 401/403、502/504，并说出各自的排查方向</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="3"> 能用一条主线讲清 HTTP/1.0 &gt; 1.1 &gt; 2 &gt; 3 各自解决了什么问题</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="4"> 能说清强缓存和协商缓存的顺序、各自的头字段、以及 ETag 为什么优于 Last-Modified</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="5"> 能解释 <code>no-cache</code> 和 <code>no-store</code> 的区别（这是陷阱题）</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="6"> 能讲清 TLS 握手的核心步骤，并解释&quot;为什么非对称 + 对称混用&quot;</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="7"> 合上书，用自己的话讲 3 分钟，中途不卡壳</li></ul>`,64)])])}const g=a(e,[["render",p]]);export{u as __pageData,g as default};
